p { margin: 0 0 1rem; color: var(--muted); }
a { color: inherit; text-decoration: none; }
.container { width: min(var(--container), 92%); margin: 0 auto; }
.section { padding: 72px 0; }
.badge {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: #eef3ff;
  color: #23395d;
  border: 1px solid #d6e0f5;
  border-radius: 999px;
  padding: .35rem .75rem;
  font-size: .8rem;
  font-weight: 600;
  margin-bottom: 1rem;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  border-radius: 12px;
  padding: .8rem 1.2rem;
  font-weight: 700;
  border: 1px solid transparent;
  transition: .2s ease;
  cursor: pointer;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { filter: brightness(.95); transform: translateY(-1px); }
.btn-secondary { border-color: var(--border); background: #fff; color: var(--primary); }
.btn-secondary:hover { border-color: #becce0; }
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(247, 249, 252, .9);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(219, 227, 239, .7);
}
.nav {
  height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo { font-weight: 800; font-size: 1.35rem; color: var(--primary); }
.logo span { color: var(--accent); }
.nav-links { display: flex; gap: 1.1rem; align-items: center; }
.nav-links a { color: #2d3a50; font-weight: 600; }
.nav-links a:hover { color: var(--accent); }
.mobile-toggle {
  display: none;
  width: 44px;
  height: 44px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fff;
  align-items: center;
  justify-content: center;
}
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -310px;
  width: 290px;
  height: 100dvh;
  background: #fff;
  box-shadow: -14px 0 34px rgba(5, 10, 22, .18);
  padding: 88px 22px 26px;
  transition: right .28s ease;
  z-index: 80;
}
.mobile-drawer.open { right: 0; }
.mobile-drawer nav { display: grid; gap: .8rem; }
.mobile-drawer a {
  padding: .75rem .9rem;
  border: 1px solid var(--border);
  border-radius: 10px;
  font-weight: 600;
}
.overlay {
  position: fixed;
  inset: 0;
  background: rgba(10, 18, 36, .46);
  opacity: 0;
  visibility: hidden;
  transition: .22s;
  z-index: 70;
}
.overlay.show { opacity: 1; visibility: visible; }
.hero {
  padding: 88px 0 70px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  gap: 2rem;
  align-items: center;
}
.hero-card {
  background: linear-gradient(160deg, #111b2e, #1f2f4d);
  color: #fff;
  border-radius: 20px;
  padding: 1.4rem;
  box-shadow: var(--shadow);
}
.hero h1 { font-size: clamp(2rem, 4.2vw, 3.3rem); color: #0e1730; }
.hero .lead { font-size: 1.06rem; max-width: 58ch; }
.kpis {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-top: 1rem;
}
.kpi {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 12px;
  padding: .9rem;
}
.kpi strong { display: block; font-size: 1.4rem; }
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.15rem;
}
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.1rem;
  box-shadow: 0 8px 22px rgba(16, 26, 44, .05);
}
.card h3 { font-size: 1.1rem; }
.icon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: #fff0e3;
  color: #b64f00;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: .65rem;
  font-size: 1.2rem;
}
.steps { display: grid; gap: 1rem; }
.step {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: .9rem;
  align-items: start;
}
.step span {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #eef3ff;
  color: #24385c;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}
.stats-band {
  background: var(--primary);
  border-radius: 18px;
  color: #fff;
  padding: 2rem;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}
.stat strong {
  font-size: clamp(1.5rem, 3.5vw, 2.2rem);
  display: block;
}
.carousel {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 1rem;
  align-items: center;
}
.carousel button {
  width: 44px;
  height: 44px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: #fff;
  cursor: pointer;
}
.price-toggle {
  display: inline-flex;
  border: 1px solid var(--border);
  border-radius: 999px;
  overflow: hidden;
}
.price-toggle button {
  border: 0;
  background: #fff;
  padding: .55rem 1rem;
  font-weight: 700;
  cursor: pointer;
}
.price-toggle button.active { background: var(--primary); color: #fff; }
.pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin-top: 1.2rem; }
.price-card ul { padding-left: 1.1rem; margin: .8rem 0 0; color: var(--muted); }
.price-card .price { font-size: 2rem; font-weight: 800; color: var(--primary); }
.price-card.highlight {
  border-color: #ffcca6;
  box-shadow: 0 16px 26px rgba(255, 122, 26, .13);
}
.faq-item { border-bottom: 1px solid var(--border); }
.faq-q {
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  font: inherit;
  font-weight: 700;
  padding: 1rem 0;
  cursor: pointer;
}
.faq-a { max-height: 0; overflow: hidden; transition: max-height .2s ease; }
.faq-item.open .faq-a { max-height: 180px; padding-bottom: .9rem; }
.cta {
  background: linear-gradient(160deg, #15213a, #0f172a);
  color: #fff;
  border-radius: 18px;
  padding: 2rem;
  text-align: center;
}
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: .9rem; }
.field label { display: block; font-weight: 700; margin-bottom: .33rem; }
.field input, .field textarea, .field select {
  width: 100%;
  border: 1px solid #cfd9e9;
  border-radius: 10px;
  padding: .7rem .8rem;
  font: inherit;
}
.field small { color: #b42318; display: none; }
.field.invalid small { display: block; }
.success-msg {
